1	-- ===========================================================================
2	-- bipar_etiqueta(saida/entrada) agora aceita container vazio (consumida).
3	--
4	-- Modelo correto: status eh ciclo do CONTAINER (gerada → em_transito → recebida).
5	-- quantidade_disponivel eh saldo INTERNO independente — so retirada/adicao avulsa
6	-- mexe. Movimentar o container (saida/entrada) NAO altera saldo.
7	--
8	-- Antes: container 'consumida' (saldo 0) ficava preso — nao podia sair de volta
9	-- pra outro lugar. Agora aceita.
10	-- ===========================================================================
11	
12	CREATE OR REPLACE FUNCTION public.bipar_etiqueta(
13	  p_uid       text,
14	  p_etapa     text,
15	  p_contexto  jsonb DEFAULT '{}'::jsonb
16	)
17	RETURNS jsonb
18	LANGUAGE plpgsql
19	SECURITY DEFINER
20	SET search_path = public
21	AS $func$
22	DECLARE
23	  v_etiqueta            public.etiquetas_qr%ROWTYPE;
24	  v_user_id             uuid := auth.uid();
25	  v_user_nome           text;
26	  v_status_anterior     text;
27	  v_status_novo         text;
28	  v_loja_id             integer;
29	  v_alertas             jsonb := '[]'::jsonb;
30	  v_referencia_tipo     text;
31	  v_referencia_id       text;
32	  v_payload             jsonb;
33	  v_pid_text            text;
34	  v_pid_int             integer;
35	  v_lote_uuid           uuid;
36	  v_produto_nome        text;
37	  v_lote_codigo         text;
38	  v_lote_validade       date;
39	  v_qty_interna         numeric;
40	BEGIN
41	  IF p_etapa NOT IN ('separacao','conferencia','entrada','saida','consumo','descarte') THEN
42	    RETURN jsonb_build_object('ok', false, 'erro', 'Etapa invalida: ' || p_etapa);
43	  END IF;
44	
45	  SELECT COALESCE(raw_user_meta_data->>'nome', email)
46	    INTO v_user_nome
47	    FROM auth.users WHERE id = v_user_id;
48	
49	  v_loja_id         := NULLIF(p_contexto->>'loja_id','')::integer;
50	  v_referencia_tipo := p_contexto->>'referencia_tipo';
51	  v_referencia_id   := p_contexto->>'referencia_id';
52	  v_payload         := p_contexto->'payload';
53	
54	  SELECT * INTO v_etiqueta FROM public.etiquetas_qr WHERE uid = p_uid;
55	
56	  IF NOT FOUND THEN
57	    IF v_payload IS NULL THEN
58	      RETURN jsonb_build_object('ok', false, 'erro', 'Etiqueta nao cadastrada e sem payload para backfill');
59	    END IF;
60	    v_pid_text := COALESCE(v_payload->>'pid', v_payload->>'p');
61	    IF v_pid_text IS NULL OR v_pid_text = '' THEN
62	      RETURN jsonb_build_object('ok', false, 'erro', 'Etiqueta nao cadastrada e payload sem produto');
63	    END IF;
64	    v_pid_int     := v_pid_text::integer;
65	    v_lote_uuid   := NULLIF(COALESCE(v_payload->>'lid', v_payload->>'l'),'')::uuid;
66	    v_qty_interna := COALESCE(NULLIF(COALESCE(v_payload->>'qty', v_payload->>'q'),'')::numeric, 1);
67	
68	    SELECT nome INTO v_produto_nome FROM public.produtos_master WHERE id = v_pid_int;
69	    IF v_lote_uuid IS NOT NULL THEN
70	      SELECT codigo, data_validade INTO v_lote_codigo, v_lote_validade FROM public.lotes WHERE id = v_lote_uuid;
71	    END IF;
72	
73	    INSERT INTO public.etiquetas_qr (
74	      uid, produto_master_id, lote_id, embalagem_nome, quantidade_interna,
75	      quantidade_disponivel, consumida_inteira,
76	      produto_nome_snapshot, lote_codigo_snapshot, lote_validade_snapshot,
77	      loja_origem_id, loja_atual_id, status, tipo_embalagem,
78	      foi_separada, separada_at, separada_por,
79	      foi_conferida, conferida_at, conferida_por,
80	      backfilled, qr_payload
81	    ) VALUES (
82	      p_uid, v_pid_int, v_lote_uuid,
83	      COALESCE(v_payload->>'emb', v_payload->>'n'),
84	      v_qty_interna, v_qty_interna, false,
85	      v_produto_nome, v_lote_codigo, v_lote_validade,
86	      NULL, v_loja_id,
87	      CASE p_etapa
88	        WHEN 'separacao'   THEN 'gerada'
89	        WHEN 'conferencia' THEN 'gerada'
90	        WHEN 'entrada'     THEN 'recebida'
91	        WHEN 'saida'       THEN 'em_transito'
92	        WHEN 'consumo'     THEN 'consumida'
93	        WHEN 'descarte'    THEN 'descartada'
94	      END,
95	      COALESCE(v_payload->>'tipo', v_payload->>'t', 'caixa'),
96	      (p_etapa = 'separacao'),
97	      CASE WHEN p_etapa = 'separacao' THEN NOW() ELSE NULL END,
98	      CASE WHEN p_etapa = 'separacao' THEN v_user_id ELSE NULL END,
99	      (p_etapa = 'conferencia'),
100	      CASE WHEN p_etapa = 'conferencia' THEN NOW() ELSE NULL END,
101	      CASE WHEN p_etapa = 'conferencia' THEN v_user_id ELSE NULL END,
102	      true, v_payload
103	    ) RETURNING * INTO v_etiqueta;
104	
105	    v_alertas := v_alertas || jsonb_build_array('Etiqueta antiga registrada retroativamente (backfill)');
106	
107	    INSERT INTO public.etiquetas_qr_eventos (etiqueta_uid, tipo_evento, etapa, status_anterior, status_novo,
108	      loja_id, usuario_id, usuario_nome, referencia_tipo, referencia_id, metadata)
109	      VALUES (p_uid, 'backfilled', 'backfill', NULL, v_etiqueta.status,
110	      v_loja_id, v_user_id, v_user_nome, v_referencia_tipo, v_referencia_id,
111	      jsonb_build_object('etapa_origem', p_etapa, 'payload', v_payload));
112	
113	    RETURN jsonb_build_object('ok', true, 'etiqueta', to_jsonb(v_etiqueta),
114	      'status_anterior', NULL, 'status_novo', v_etiqueta.status,
115	      'alertas', v_alertas, 'backfilled', true);
116	  END IF;
117	
118	  v_status_anterior := v_etiqueta.status;
119	
120	  IF v_etiqueta.status = 'descartada' THEN
121	    RETURN jsonb_build_object('ok', false,
122	      'erro', 'Etiqueta descartada' || CASE WHEN v_etiqueta.replaced_by_uid IS NOT NULL THEN ' (substituida por ' || v_etiqueta.replaced_by_uid || ')' ELSE '' END,
123	      'etiqueta', to_jsonb(v_etiqueta));
124	  END IF;
125	
126	  IF v_etiqueta.lote_validade_snapshot IS NOT NULL AND v_etiqueta.lote_validade_snapshot < CURRENT_DATE THEN
127	    v_alertas := v_alertas || jsonb_build_array(format('LOTE VENCIDO em %s', to_char(v_etiqueta.lote_validade_snapshot,'DD/MM/YYYY')));
128	  END IF;
129	
130	  IF p_etapa = 'separacao' THEN
131	    IF v_etiqueta.foi_separada THEN
132	      RETURN jsonb_build_object('ok', false,
133	        'erro', format('Etiqueta %s ja esta com status "separada" — bip duplicado nesta etapa', p_uid),
134	        'etiqueta', to_jsonb(v_etiqueta), 'status_anterior', v_status_anterior, 'status_novo', v_status_anterior);
135	    END IF;
136	    UPDATE public.etiquetas_qr SET foi_separada = TRUE, separada_at = NOW(), separada_por = v_user_id,
137	      loja_atual_id = COALESCE(v_loja_id, loja_atual_id) WHERE uid = p_uid RETURNING * INTO v_etiqueta;
138	    INSERT INTO public.etiquetas_qr_eventos (etiqueta_uid, tipo_evento, etapa, status_anterior, status_novo,
139	      loja_id, usuario_id, usuario_nome, referencia_tipo, referencia_id, metadata)
140	      VALUES (p_uid, 'bipada_separacao', 'separacao', v_status_anterior, v_status_anterior,
141	      v_loja_id, v_user_id, v_user_nome, v_referencia_tipo, v_referencia_id, p_contexto - 'payload');
142	    RETURN jsonb_build_object('ok', true, 'etiqueta', to_jsonb(v_etiqueta),
143	      'status_anterior', v_status_anterior, 'status_novo', v_status_anterior, 'alertas', v_alertas, 'backfilled', false);
144	  END IF;
145	
146	  IF p_etapa = 'conferencia' THEN
147	    IF v_etiqueta.foi_conferida THEN
148	      RETURN jsonb_build_object('ok', false,
149	        'erro', format('Etiqueta %s ja esta com status "conferida" — bip duplicado nesta etapa', p_uid),
150	        'etiqueta', to_jsonb(v_etiqueta), 'status_anterior', v_status_anterior, 'status_novo', v_status_anterior);
151	    END IF;
152	    UPDATE public.etiquetas_qr SET foi_conferida = TRUE, conferida_at = NOW(), conferida_por = v_user_id,
153	      loja_atual_id = COALESCE(v_loja_id, loja_atual_id) WHERE uid = p_uid RETURNING * INTO v_etiqueta;
154	    INSERT INTO public.etiquetas_qr_eventos (etiqueta_uid, tipo_evento, etapa, status_anterior, status_novo,
155	      loja_id, usuario_id, usuario_nome, referencia_tipo, referencia_id, metadata)
156	      VALUES (p_uid, 'bipada_conferencia', 'conferencia', v_status_anterior, v_status_anterior,
157	      v_loja_id, v_user_id, v_user_nome, v_referencia_tipo, v_referencia_id, p_contexto - 'payload');
158	    RETURN jsonb_build_object('ok', true, 'etiqueta', to_jsonb(v_etiqueta),
159	      'status_anterior', v_status_anterior, 'status_novo', v_status_anterior, 'alertas', v_alertas, 'backfilled', false);
160	  END IF;
161	
162	  -- saida/entrada/consumo/descarte = ciclo fisico do CONTAINER.
163	  -- Saldo (quantidade_disponivel) NAO eh tocado aqui — so retirada/adicao avulsa mexe.
164	  -- Aceita ate status 'consumida' (container vazio pode ser movimentado de volta).
165	  v_status_novo := CASE p_etapa
166	    WHEN 'saida' THEN
167	      CASE WHEN v_etiqueta.status IN ('gerada','recebida','aberta','consumida') THEN 'em_transito' ELSE NULL END
168	    WHEN 'entrada' THEN
169	      CASE WHEN v_etiqueta.status IN ('em_transito','gerada','aberta','consumida') THEN 'recebida'
170	           WHEN v_etiqueta.status = 'recebida' AND v_loja_id IS DISTINCT FROM v_etiqueta.loja_atual_id THEN 'recebida'
171	           ELSE NULL END
172	    WHEN 'consumo'  THEN 'consumida'
173	    WHEN 'descarte' THEN 'descartada'
174	  END;
175	
176	  IF v_status_novo IS NULL THEN
177	    RETURN jsonb_build_object('ok', false,
178	      'erro', format('Etiqueta %s ja esta com status "%s" — bip duplicado nesta etapa', p_uid, v_status_anterior),
179	      'etiqueta', to_jsonb(v_etiqueta));
180	  END IF;
181	
182	  UPDATE public.etiquetas_qr SET status = v_status_novo,
183	    loja_atual_id = COALESCE(v_loja_id, loja_atual_id) WHERE uid = p_uid RETURNING * INTO v_etiqueta;
184	
185	  INSERT INTO public.etiquetas_qr_eventos (etiqueta_uid, tipo_evento, etapa, status_anterior, status_novo,
186	    loja_id, usuario_id, usuario_nome, referencia_tipo, referencia_id, metadata)
187	    VALUES (p_uid, 'bipada_' || p_etapa, p_etapa, v_status_anterior, v_status_novo,
188	    v_loja_id, v_user_id, v_user_nome, v_referencia_tipo, v_referencia_id, p_contexto - 'payload');
189	
190	  RETURN jsonb_build_object('ok', true, 'etiqueta', to_jsonb(v_etiqueta),
191	    'status_anterior', v_status_anterior, 'status_novo', v_status_novo, 'alertas', v_alertas, 'backfilled', false);
192	END;
193	$func$;
194

1	import { useState, useEffect } from "react";
2	import { FileText, Filter, ArrowLeft, Sun, Moon, Leaf, User as UserIcon, LogOut, ChevronLeft, ChevronRight, Search, X } from "lucide-react";
3	import { Input } from "@/shared/ui/input";
4	import { Card, CardContent, CardDescription, CardHeader, CardTitle } from "@/shared/ui/card";
5	import { Table, TableBody, TableCell, TableHead, TableHeader, TableRow } from "@/shared/ui/table";
6	import { Badge } from "@/shared/ui/badge";
7	import { Select, SelectContent, SelectItem, SelectTrigger, SelectValue } from "@/shared/ui/select";
8	import { supabase } from "@/integrations/supabase/client";
9	import { toast } from "@/shared/hooks/use-toast";
10	import { format } from "date-fns";
11	import { ptBR } from "date-fns/locale";
12	import { useStoreFilter } from "@/shared/hooks/useStoreData";
13	import { PermissionBlur } from "@/shared/ui/PermissionBlur";
14	import { usePermissions } from "@/shared/hooks/usePermissions";
15	import { useIsMobile } from "@/shared/hooks/use-mobile";
16	import { useTheme } from "next-themes";
17	import { useAuth } from "@/hooks/useAuth";
18	import { useStore } from "@/shared/contexts/StoreContext";
19	import { StoreSelector } from "@/shared/ui/StoreSelector";
20	import { useNavigate } from "react-router-dom";
21	import { cn } from "@/shared/lib/utils";
22	import { Button } from "@/shared/ui/button";
23	import { useMiaMovimentacoesActions } from '@/features/mia/model/hooks';
24	import {
25	  DropdownMenu,
26	  DropdownMenuContent,
27	  DropdownMenuItem,
28	  DropdownMenuLabel,
29	  DropdownMenuSeparator,
30	  DropdownMenuTrigger,
31	} from "@/shared/ui/dropdown-menu";
32	import { Avatar, AvatarFallback } from "@/shared/ui/avatar";
33	
34	interface Movement {
35	  movimentacao_id: number;
36	  tipo_movimentacao: string;
37	  produto_nome: string;
38	  categoria_nome: string;
39	  categoria_emoji: string;
40	  quantidade: number;
41	  quantidade_anterior: number;
42	  quantidade_nova: number;
43	  unidade_medida: string;
44	  usuario_nome: string;
45	  data_movimentacao: string;
46	  motivo: string;
47	  observacoes: string;
48	  codigo_interno: number;
49	  lote_codigo?: string;
50	  lote_validade?: string;
51	}
52	
53	export default function Movimentacoes() {
54	  const [movements, setMovements] = useState<Movement[]>([]);
55	  const [isLoading, setIsLoading] = useState(true);
56	  const [sectorFilter, setSectorFilter] = useState<string>("todos");
57	  const [sectors, setSectors] = useState<string[]>([]);
58	  const [productSearch, setProductSearch] = useState<string>("");
59	  const { hasData, applyStoreFilter, storeId } = useStoreFilter();
60	  const { canViewEstoque, hasPermission, isAdmin } = usePermissions();
61	
62	  const isMobile = useIsMobile();
63	  const { theme, setTheme } = useTheme();
64	  const navigate = useNavigate();
65	  const { userProfile, user, signOut } = useAuth();
66	  const [serverVersion, setServerVersion] = useState<string | null>(null);
67	  const [currentPage, setCurrentPage] = useState(1);
68	  const ITEMS_PER_PAGE = 20;
69	
70	  useMiaMovimentacoesActions({
71	    setSectorFilter,
72	    setProductSearch,
73	    setCurrentPage,
74	    movements,
75	  });
76	
77	  useEffect(() => {
78	    if (hasData) {
79	      fetchSectors();
80	      fetchMovements();
81	    }
82	  }, [hasData, storeId]);
83	
84	  useEffect(() => {
85	    setCurrentPage(1);
86	    // fetchMovements will be called by the next useEffect because currentPage changes or we call it explicitly? 
87	    // Actually, if we setPage(1), and it was 1, it won't trigger. 
88	    // We should call fetchMovements() here if page is 1, or depend on currentPage
89	  }, [sectorFilter, productSearch]);
90	
91	  useEffect(() => {
92	    fetchMovements();
93	  }, [currentPage, sectorFilter, storeId, hasData, productSearch]);
94	
95	  useEffect(() => {
96	    if (isMobile) {
97	      fetch(`/version.json?t=${Date.now()}`)
98	        .then(res => res.json())
99	        .then(data => setServerVersion(data.version))
100	        .catch(err => console.error("Failed to fetch server version", err));
101	    }
102	  }, [isMobile]);
103	
104	  const fetchSectors = async () => {
105	    try {
106	      if (!hasData) {
107	        setSectors([]);
108	        return;
109	      }
110	
111	      // Use standard view for sectors
112	      // @ts-expect-error - supabase view type not in generated types
113	      const query = supabase
114	        .from('vw_produtos_estoque_lojas')
115	        .select('setor')
116	        .eq('loja_id', storeId) // Explicitly filter by store
117	        .not('setor', 'is', null);
118	
119	      // query = applyStoreFilter(query); // storeId is already applied above explicitly or via hook if passed, but let's be safe. 
120	      // applyStoreFilter uses the context storeId. If I use vw_produtos_estoque_lojas which has loja_id, it fits.
121	
122	      const { data, error } = await query;
123	
124	      if (error) throw error;
125	
126	      const uniqueSectors = [...new Set(data?.map((p: any) => p.setor) || [])]
127	        .filter(sector => sector && sector.toLowerCase() !== 'compras');
128	      setSectors(uniqueSectors as string[]);
129	    } catch (error) {
130	      console.error('Erro ao carregar setores:', error);
131	    }
132	  };
133	
134	  const fetchMovements = async () => {
135	    try {
136	      if (!hasData) {
137	        setMovements([]);
138	        return;
139	      }
140	
141	      const from = (currentPage - 1) * ITEMS_PER_PAGE;
142	      const to = from + ITEMS_PER_PAGE - 1;
143	
144	      // If there's a product search, prioritize it - search ALL movements without pagination
145	      if (productSearch.trim()) {
146	        const term = productSearch.trim();
147	        let searchQuery = supabase
148	          .from('view_movimentacoes_recentes')
149	          .select('*')
150	          .or(`produto_nome.ilike.%${term}%,codigo_interno_str.ilike.%${term}%,lote_codigo.ilike.%${term}%`)
151	          .order('data_movimentacao', { ascending: false })
152	          .limit(500); // High limit to get comprehensive results for the search
153	
154	        searchQuery = applyStoreFilter(searchQuery);
155	        const { data: searchData, error: searchError } = await searchQuery;
156	
157	        if (searchError) throw searchError;
158	        setMovements(searchData || []);
159	        return;
160	      }
161	
162	      if (sectorFilter !== "todos") {
163	        // Buscar produtos do setor - uses standard view
164	        // @ts-expect-error - supabase view type not in generated types
165	        const produtosQuery = supabase
166	          .from('vw_produtos_estoque_lojas')
167	          .select('produto_master_id, nome')
168	          .eq('loja_id', storeId)
169	          .eq('setor', sectorFilter);
170	
171	        const { data: produtos, error: produtosError } = await produtosQuery;
172	
173	        if (produtosError) throw produtosError;
174	
175	        if (produtos && produtos.length > 0) {
176	          const produtoNomes = produtos.map((p: any) => p.nome);
177	
178	          // Buscar movimentações filtrando pelo nome do produto
179	          let movQuery = supabase
180	            .from('view_movimentacoes_recentes')
181	            .select('*')
182	            .in('produto_nome', produtoNomes)
183	            .order('data_movimentacao', { ascending: false })
184	            .range(from, to);
185	
186	          movQuery = applyStoreFilter(movQuery);
187	          const { data: movData, error: movError } = await movQuery;
188	
189	          if (movError) throw movError;
190	          setMovements(movData || []);
191	        } else {
192	          setMovements([]);
193	        }
194	      } else {
195	        // Buscar todas as movimentações
196	        let allMovQuery = supabase
197	          .from('view_movimentacoes_recentes')
198	          .select('*')
199	          .order('data_movimentacao', { ascending: false })
200	          .range(from, to);
201	
202	        allMovQuery = applyStoreFilter(allMovQuery);
203	        const { data: allMovData, error: allMovError } = await allMovQuery;
204	
205	        if (allMovError) throw allMovError;
206	        setMovements(allMovData || []);
207	      }
208	    } catch (error) {
209	      console.error('Erro ao carregar movimentações:', error);
210	      toast({
211	        title: "Erro",
212	        description: "Não foi possível carregar as movimentações",
213	        variant: "destructive",
214	      });
215	    } finally {
216	      setIsLoading(false);
217	    }
218	  };
219	
220	  const getMovementColor = (type: string) => {
221	    return type === 'entrada' ? 'text-green-600' : 'text-red-600';
222	  };
223	
224	  const formatMovementType = (type: string) => {
225	    if (type === 'entrada') return 'Entrada';
226	    if (type === 'saida') return 'Saída';
227	    if (type === 'perda') return 'Perda';
228	    if (type === 'mudanca_categoria') return 'Mudança de categoria';
229	    if (type === 'cadastro') return 'Cadastro';
230	    if (type === 'exclusao') return 'Exclusão';
231	    return type;
232	  };
233	
234	  if (isLoading) {
235	    return (
236	      <div className="flex items-center justify-center min-h-screen">
237	        <div className="animate-spin rounded-full h-32 w-32 border-b-2 border-primary"></div>
238	      </div>
239	    );
240	  }
241	
242	  const hasAccess = hasPermission("view_movimentacoes") || canViewEstoque() || isAdmin();
243	
244	  if (isMobile) {
245	    return (
246	      <PermissionBlur hasPermission={hasAccess} moduleName="Estoque" permissionName="view_movimentacoes">
247	        <div className="flex flex-col min-h-[100dvh] bg-white dark:bg-[#0A0A0A] overflow-x-hidden relative font-sans">
248	          {/* Store Awning Stripe Effect (Top Border) */}
249	          <div className="absolute top-0 left-0 right-0 h-1.5 bg-[repeating-linear-gradient(90deg,#57715B,#57715B_20px,#ffffff_20px,#ffffff_40px)] opacity-80 z-50" />
250	
251	          {/* Animated Plant Background Elements */}
252	          <div className="absolute top-[-5%] right-[-10%] w-[300px] h-[300px] opacity-[0.03] dark:opacity-[0.05] pointer-events-none animate-pulse" style={{ animationDuration: '10s' }}>
253	            <Leaf className="w-full h-full text-[#57715B] rotate-12" />
254	          </div>
255	
256	          {/* Header */}
257	          <div className="flex justify-between items-center px-6 pt-8 pb-2 z-20">
258	            <div className="flex items-center gap-3">
259	              <Button variant="ghost" size="icon" onClick={() => navigate(-1)} className="h-10 w-10 -ml-2 rounded-full hover:bg-black/5 dark:hover:bg-white/10">
260	                <ArrowLeft className="h-6 w-6 text-[#57715B] dark:text-[#E6DCCF]" />
261	              </Button>
