711	-- ─────────────────────────────────────────────────────────────────────────────
712	-- 8) bipar_retirada_avulsa: contexto.destino = 'expositora' → a própria RPC
713	--    registra a movimentação de saída (motivo 'retirada_avulsa_exposicao');
714	--    o trigger credita a expositora. Frontend NÃO insere movimentação nesse caso
715	--    (resposta traz movimentacao_registrada = true).
716	--    Sem destino (default 'saida'): comportamento idêntico ao atual.
717	-- ─────────────────────────────────────────────────────────────────────────────
718	
719	CREATE OR REPLACE FUNCTION public.bipar_retirada_avulsa(p_uid text, p_quantidade numeric, p_contexto jsonb DEFAULT '{}'::jsonb)
720	 RETURNS jsonb
721	 LANGUAGE plpgsql
722	 SECURITY DEFINER
723	 SET search_path TO 'public'
724	AS $function$
725	DECLARE
726	  v_etiqueta            public.etiquetas_qr%ROWTYPE;
727	  v_user_id             uuid := auth.uid();
728	  v_user_nome           text;
729	  v_loja_id             integer;
730	  v_referencia_tipo     text;
731	  v_referencia_id       text;
732	  v_payload             jsonb;
733	  v_disponivel_apos     numeric;
734	  v_status_anterior     text;
735	  v_status_novo         text;
736	  v_pid_text            text;
737	  v_pid_int             integer;
738	  v_lote_uuid           uuid;
739	  v_produto_nome        text;
740	  v_lote_codigo         text;
741	  v_lote_validade       date;
742	  v_qty_interna         numeric;
743	  -- destino expositora
744	  v_destino             text;
745	  v_loja_eff            integer;
746	  v_est_ant             numeric;
747	  v_mov_registrada      boolean := false;
748	BEGIN
749	  IF p_quantidade IS NULL OR p_quantidade <= 0 THEN
750	    RETURN jsonb_build_object('ok', false, 'erro', 'Quantidade deve ser maior que zero');
751	  END IF;
752	
753	  v_loja_id         := NULLIF(p_contexto->>'loja_id','')::integer;
754	  v_referencia_tipo := p_contexto->>'referencia_tipo';
755	  v_referencia_id   := p_contexto->>'referencia_id';
756	  v_payload         := p_contexto->'payload';
757	  v_destino         := COALESCE(NULLIF(p_contexto->>'destino',''), 'saida');
758	
759	  IF v_destino NOT IN ('saida','expositora') THEN
760	    RETURN jsonb_build_object('ok', false, 'erro', 'Destino invalido: ' || v_destino);
761	  END IF;
762	
763	  SELECT * INTO v_etiqueta FROM public.etiquetas_qr WHERE uid = p_uid FOR UPDATE;
764	
765	  -- ===== BACKFILL legacy: etiqueta sem row mas com payload no QR =====
766	  IF NOT FOUND THEN
767	    IF v_payload IS NULL THEN
768	      RETURN jsonb_build_object('ok', false, 'erro', 'Etiqueta nao encontrada (sem payload para backfill)');
769	    END IF;
770	    v_pid_text := COALESCE(v_payload->>'pid', v_payload->>'p');
771	    IF v_pid_text IS NULL OR v_pid_text = '' THEN
772	      RETURN jsonb_build_object('ok', false, 'erro', 'Etiqueta nao cadastrada e payload sem produto');
773	    END IF;
774	    v_pid_int     := v_pid_text::integer;
775	    v_lote_uuid   := NULLIF(COALESCE(v_payload->>'lid', v_payload->>'l'),'')::uuid;
776	    v_qty_interna := COALESCE(NULLIF(COALESCE(v_payload->>'qty', v_payload->>'q'),'')::numeric, 1);
777	
778	    SELECT nome INTO v_produto_nome FROM public.produtos_master WHERE id = v_pid_int;
779	    IF v_lote_uuid IS NOT NULL THEN
780	      SELECT codigo, data_validade INTO v_lote_codigo, v_lote_validade FROM public.lotes WHERE id = v_lote_uuid;
781	    END IF;
782	
783	    INSERT INTO public.etiquetas_qr (
784	      uid, produto_master_id, lote_id, embalagem_nome, quantidade_interna,
785	      quantidade_disponivel, consumida_inteira,
786	      produto_nome_snapshot, lote_codigo_snapshot, lote_validade_snapshot,
787	      loja_origem_id, loja_atual_id, status, tipo_embalagem,
788	      backfilled, qr_payload
789	    ) VALUES (
790	      p_uid, v_pid_int, v_lote_uuid,
791	      COALESCE(v_payload->>'emb', v_payload->>'n'),
792	      v_qty_interna, v_qty_interna, false,
793	      v_produto_nome, v_lote_codigo, v_lote_validade,
794	      NULL, v_loja_id, 'gerada',
795	      COALESCE(v_payload->>'tipo', v_payload->>'t', 'caixa'),
796	      true, v_payload
797	    )
798	    RETURNING * INTO v_etiqueta;
799	
800	    INSERT INTO public.etiquetas_qr_eventos (etiqueta_uid, tipo_evento, etapa, status_anterior, status_novo,
801	      loja_id, usuario_id, usuario_nome, referencia_tipo, referencia_id, metadata)
802	      VALUES (p_uid, 'backfilled', 'backfill', NULL, 'gerada',
803	      v_loja_id, v_user_id, COALESCE((SELECT raw_user_meta_data->>'nome' FROM auth.users WHERE id = v_user_id), NULL),
804	      v_referencia_tipo, v_referencia_id,
805	      jsonb_build_object('etapa_origem', 'retirada_avulsa', 'payload', v_payload));
806	  END IF;
807	
808	  IF v_etiqueta.consumida_inteira OR v_etiqueta.status = 'consumida' THEN
809	    RETURN jsonb_build_object('ok', false,
810	      'erro', format('Etiqueta %s ja foi consumida totalmente', p_uid),
811	      'etiqueta', to_jsonb(v_etiqueta));
812	  END IF;
813	  IF v_etiqueta.status = 'descartada' THEN
814	    RETURN jsonb_build_object('ok', false, 'erro', 'Etiqueta descartada', 'etiqueta', to_jsonb(v_etiqueta));
815	  END IF;
816	
817	  IF p_quantidade > v_etiqueta.quantidade_disponivel THEN
818	    RETURN jsonb_build_object('ok', false,
819	      'erro', format('Container so tem %s disponivel (pediu %s)', v_etiqueta.quantidade_disponivel, p_quantidade),
820	      'etiqueta', to_jsonb(v_etiqueta));
821	  END IF;
822	
823	  -- destino expositora exige loja conhecida — validar ANTES de qualquer escrita
824	  v_loja_eff := COALESCE(v_loja_id, v_etiqueta.loja_atual_id);
825	  IF v_destino = 'expositora' AND v_loja_eff IS NULL THEN
826	    RETURN jsonb_build_object('ok', false, 'erro', 'Destino expositora exige loja conhecida (contexto ou etiqueta)');
827	  END IF;
828	
829	  v_disponivel_apos := v_etiqueta.quantidade_disponivel - p_quantidade;
830	  v_status_anterior := v_etiqueta.status;
831	  v_status_novo := CASE
832	    WHEN v_disponivel_apos = 0 THEN 'consumida'
833	    WHEN v_disponivel_apos < v_etiqueta.quantidade_interna THEN 'aberta'
834	    ELSE v_status_anterior
835	  END;
836	
837	  UPDATE public.etiquetas_qr SET
838	    quantidade_disponivel = v_disponivel_apos,
839	    consumida_inteira     = (v_disponivel_apos = 0),
840	    status                = v_status_novo,
841	    loja_atual_id         = COALESCE(v_loja_id, loja_atual_id)
842	  WHERE uid = p_uid RETURNING * INTO v_etiqueta;
843	
844	  SELECT COALESCE(raw_user_meta_data->>'nome', email) INTO v_user_nome FROM auth.users WHERE id = v_user_id;
845	
846	  INSERT INTO public.etiquetas_qr_eventos (etiqueta_uid, tipo_evento, etapa, status_anterior, status_novo,
847	    loja_id, usuario_id, usuario_nome, referencia_tipo, referencia_id, metadata)
848	    VALUES (p_uid,
849	      CASE WHEN v_disponivel_apos = 0 THEN 'consumida_total' ELSE 'retirada_avulsa' END,
850	      'consumo', v_status_anterior, v_status_novo,
851	      v_loja_id, v_user_id, v_user_nome, v_referencia_tipo, v_referencia_id,
852	      jsonb_build_object(
853	        'quantidade_retirada', p_quantidade,
854	        'quantidade_disponivel_antes', v_etiqueta.quantidade_interna - v_disponivel_apos + p_quantidade,
855	        'quantidade_disponivel_apos', v_disponivel_apos,
856	        'consumida_inteira', v_etiqueta.consumida_inteira,
857	        'destino', v_destino));
858	
859	  -- destino expositora: movimentação de saída do estoque registrada AQUI
860	  -- (trigger credita a expositora na mesma transação)
861	  IF v_destino = 'expositora' THEN
862	    SELECT quantidade_atual INTO v_est_ant
863	      FROM public.estoque
864	     WHERE produto_master_id = v_etiqueta.produto_master_id AND loja_id = v_loja_eff
865	     FOR UPDATE;
866	    v_est_ant := COALESCE(v_est_ant, 0);
867	
868	    INSERT INTO public.movimentacoes (
869	      produto_master_id, tipo_movimentacao, quantidade,
870	      quantidade_anterior, quantidade_nova, motivo, observacoes,
871	      data_movimentacao, loja_id, lote_id, etiqueta_qr_uid
872	    ) VALUES (
873	      v_etiqueta.produto_master_id, 'saida', p_quantidade,
874	      v_est_ant, v_est_ant - p_quantidade,
875	      'retirada_avulsa_exposicao',
876	      format('Retirada avulsa pra vitrine — UID %s', p_uid),
877	      NOW(), v_loja_eff, v_etiqueta.lote_id, p_uid
878	    );
879	    v_mov_registrada := true;
880	  END IF;
881	
882	  RETURN jsonb_build_object('ok', true, 'etiqueta', to_jsonb(v_etiqueta),
883	    'quantidade_retirada', p_quantidade, 'quantidade_disponivel', v_disponivel_apos,
884	    'consumida_inteira', v_etiqueta.consumida_inteira,
885	    'status_anterior', v_status_anterior, 'status_novo', v_status_novo,
886	    'destino', v_destino, 'movimentacao_registrada', v_mov_registrada);
887	END;
888	$function$;
