944	-- ─────────────────────────────────────────────────────────────────────────────
945	-- 10) atualizar_estoque_e_alertas: alertas passam a comparar o TOTAL EM LOJA
946	--     (estoque câmara + expositora) — evita alarme falso quando o estoque
947	--     simplesmente subiu pra vitrine. Upsert de estoque inalterado.
948	--     Ramo legacy (produto_id) inalterado.
949	-- ─────────────────────────────────────────────────────────────────────────────
950	
951	CREATE OR REPLACE FUNCTION public.atualizar_estoque_e_alertas()
952	 RETURNS trigger
953	 LANGUAGE plpgsql
954	 SET search_path TO 'public', 'pg_temp'
955	AS $function$
956	DECLARE
957	    estoque_atual DECIMAL(10,3);
958	    estoque_minimo DECIMAL(10,3);
959	    expositora_qtd DECIMAL(10,3);
960	    total_loja DECIMAL(10,3);
961	BEGIN
962	    -- Scenario 1: New System (Master ID)
963	    IF NEW.produto_master_id IS NOT NULL THEN
964	        -- Upsert into estoque using (produto_master_id, loja_id)
965	        -- We assume 'estoque_produto_master_loja_unique' constraint exists on (produto_master_id, loja_id)
966	        INSERT INTO estoque (produto_master_id, quantidade_atual, ultima_movimentacao, ultimo_usuario_id, loja_id)
967	        VALUES (NEW.produto_master_id, NEW.quantidade_nova, NEW.data_movimentacao, NEW.usuario_id, NEW.loja_id)
968	        ON CONFLICT (produto_master_id, loja_id)
969	        DO UPDATE SET
970	            quantidade_atual = EXCLUDED.quantidade_atual,
971	            ultima_movimentacao = EXCLUDED.ultima_movimentacao,
972	            ultimo_usuario_id = EXCLUDED.ultimo_usuario_id,
973	            updated_at = NOW();
974	
975	        -- Check Alerts (sobre o TOTAL em loja: câmara + expositora)
976	        SELECT quantidade_atual, quantidade_minima
977	        INTO estoque_atual, estoque_minimo
978	        FROM estoque
979	        WHERE produto_master_id = NEW.produto_master_id AND loja_id = NEW.loja_id;
980	
981	        SELECT quantidade INTO expositora_qtd
982	        FROM expositora_estoque
983	        WHERE produto_master_id = NEW.produto_master_id AND loja_id = NEW.loja_id;
984	
985	        total_loja := COALESCE(estoque_atual, 0) + COALESCE(expositora_qtd, 0);
986	
987	        IF estoque_atual IS NOT NULL AND estoque_minimo IS NOT NULL THEN
988	            IF total_loja <= 0 THEN
989	                INSERT INTO alertas_estoque (produto_master_id, loja_id, tipo_alerta, quantidade_atual, quantidade_minima)
990	                VALUES (NEW.produto_master_id, NEW.loja_id, 'sem_estoque', total_loja, estoque_minimo);
991	            ELSIF total_loja <= (estoque_minimo * 0.5) THEN
992	                INSERT INTO alertas_estoque (produto_master_id, loja_id, tipo_alerta, quantidade_atual, quantidade_minima)
993	                VALUES (NEW.produto_master_id, NEW.loja_id, 'critico', total_loja, estoque_minimo);
994	            ELSIF total_loja <= estoque_minimo THEN
995	                INSERT INTO alertas_estoque (produto_master_id, loja_id, tipo_alerta, quantidade_atual, quantidade_minima)
996	                VALUES (NEW.produto_master_id, NEW.loja_id, 'baixo', total_loja, estoque_minimo);
997	            END IF;
998	        END IF;
999	
1000	    -- Scenario 2: Legacy System (Product ID)
1001	    ELSIF NEW.produto_id IS NOT NULL THEN
1002	        -- Upsert into estoque using (produto_id, loja_id)
1003	        INSERT INTO estoque (produto_id, quantidade_atual, ultima_movimentacao, ultimo_usuario_id, loja_id)
1004	        VALUES (NEW.produto_id, NEW.quantidade_nova, NEW.data_movimentacao, NEW.usuario_id, NEW.loja_id)
1005	        ON CONFLICT (produto_id, loja_id)
1006	        DO UPDATE SET
1007	            quantidade_atual = EXCLUDED.quantidade_atual,
1008	            ultima_movimentacao = EXCLUDED.ultima_movimentacao,
1009	            ultimo_usuario_id = EXCLUDED.ultimo_usuario_id,
1010	            updated_at = NOW();
1011	
1012	        -- Check Alerts
1013	        SELECT quantidade_atual, quantidade_minima
1014	        INTO estoque_atual, estoque_minimo
1015	        FROM estoque
1016	        WHERE produto_id = NEW.produto_id AND loja_id = NEW.loja_id;
1017	
1018	        IF estoque_atual IS NOT NULL AND estoque_minimo IS NOT NULL THEN
1019	             IF estoque_atual <= 0 THEN
1020	                INSERT INTO alertas_estoque (produto_id, loja_id, tipo_alerta, quantidade_atual, quantidade_minima)
1021	                VALUES (NEW.produto_id, NEW.loja_id, 'sem_estoque', estoque_atual, estoque_minimo);
1022	            ELSIF estoque_atual <= (estoque_minimo * 0.5) THEN
