9	CREATE OR REPLACE FUNCTION public.ajustar_lote_contagem(
10	  p_lote_id uuid,
11	  p_produto_master_id integer,
12	  p_loja_id integer,
13	  p_delta numeric,
14	  p_motivo text DEFAULT 'contagem_caixa',
15	  p_observacoes text DEFAULT NULL
16	)
17	RETURNS jsonb
18	LANGUAGE plpgsql
19	SECURITY DEFINER
20	SET search_path TO 'public'
21	AS $function$
22	DECLARE
23	  v_usuario_id integer;
24	  v_lote_id uuid := p_lote_id;
25	  v_anterior numeric;
26	  v_nova numeric;
27	  v_eff numeric;
28	  v_tipo text;
29	BEGIN
30	  IF p_produto_master_id IS NULL OR p_loja_id IS NULL THEN
31	    RETURN jsonb_build_object('ok', false, 'erro', 'produto/loja obrigatorios');
32	  END IF;
33	  IF p_delta IS NULL OR p_delta = 0 THEN
34	    RETURN jsonb_build_object('ok', true, 'noop', true);
35	  END IF;
36	
37	  -- lote vivo ou NULL — defesa contra id morto
38	  IF v_lote_id IS NOT NULL
39	     AND NOT EXISTS (SELECT 1 FROM public.lotes WHERE id = v_lote_id) THEN
40	    v_lote_id := NULL;
41	  END IF;
42	
43	  BEGIN
44	    v_usuario_id := public.get_usuario_id_from_auth(auth.uid());
45	  EXCEPTION WHEN OTHERS THEN
46	    v_usuario_id := NULL;
47	  END;
48	
49	  -- trava o saldo agregado para calcular delta efetivo sem corrida
50	  SELECT COALESCE(quantidade_atual, 0) INTO v_anterior
51	    FROM public.estoque
52	   WHERE produto_master_id = p_produto_master_id AND loja_id = p_loja_id
53	   FOR UPDATE;
54	  v_anterior := COALESCE(v_anterior, 0);
55	
56	  v_nova := GREATEST(0, v_anterior + p_delta);
57	  v_eff := v_nova - v_anterior;
58	  IF v_eff = 0 THEN
59	    RETURN jsonb_build_object('ok', true, 'noop', true, 'saldo', v_nova);
60	  END IF;
61	
62	  v_tipo := CASE WHEN v_eff > 0 THEN 'entrada' ELSE 'saida' END;
63	
64	  INSERT INTO public.movimentacoes (
65	    produto_master_id, tipo_movimentacao, quantidade,
66	    quantidade_anterior, quantidade_nova, motivo, observacoes,
67	    data_movimentacao, loja_id, lote_id, usuario_id
68	  ) VALUES (
69	    p_produto_master_id, v_tipo, ABS(v_eff),
70	    v_anterior, v_nova, COALESCE(p_motivo, 'contagem_caixa'), p_observacoes,
71	    now(), p_loja_id, v_lote_id, v_usuario_id
72	  );
73	
74	  RETURN jsonb_build_object(
75	    'ok', true, 'saldo_anterior', v_anterior, 'saldo', v_nova, 'lote_id', v_lote_id
76	  );
77	END;
78	$function$;
79	
80	-- Estende o trigger de sync para reconhecer os motivos da contagem manual,
81	-- nao so 'scanner_lote'. Assim a baixa/ajuste de caixa na contagem mantem
82	-- estoque_lotes coerente pelos mesmos trilhos do scanner.
83	CREATE OR REPLACE FUNCTION public.tg_movimentacoes_sync_estoque_lotes()
84	 RETURNS trigger
85	 LANGUAGE plpgsql
86	 SECURITY DEFINER
87	 SET search_path TO 'public'
88	AS $function$
89	BEGIN
90	  IF NEW.motivo IS DISTINCT FROM 'scanner_lote'
91	     AND NEW.motivo IS DISTINCT FROM 'contagem_caixa'
92	     AND NEW.motivo IS DISTINCT FROM 'ajuste_lote_manual' THEN
93	    RETURN NEW;
94	  END IF;
95	
96	  IF NEW.lote_id IS NULL OR NEW.produto_master_id IS NULL THEN
97	    RETURN NEW;
98	  END IF;
99	
100	  -- Sinaliza que a alteracao em estoque_lotes veio de uma movimentacao,
101	  -- pra sync_estoque_from_lotes NAO criar lancamento fantasma.
102	  PERFORM set_config('app.skip_lote_reconcile', '1', true);
103	
104	  IF NEW.tipo_movimentacao = 'entrada' THEN
105	    UPDATE public.estoque_lotes
106	       SET quantidade = GREATEST(0, quantidade + NEW.quantidade)
107	     WHERE lote_id = NEW.lote_id
108	       AND produto_id = NEW.produto_master_id
109	       AND loja_id = NEW.loja_id;
110	
111	  ELSIF NEW.tipo_movimentacao = 'saida' THEN
112	    UPDATE public.estoque_lotes
113	       SET quantidade = GREATEST(0, quantidade - NEW.quantidade)
114	     WHERE lote_id = NEW.lote_id
115	       AND produto_id = NEW.produto_master_id
116	       AND loja_id = NEW.loja_id;
117	  END IF;
118	
119	  IF NOT FOUND AND NEW.tipo_movimentacao = 'entrada' THEN
120	    INSERT INTO public.estoque_lotes (lote_id, produto_id, loja_id, quantidade)
121	    VALUES (NEW.lote_id, NEW.produto_master_id, NEW.loja_id, NEW.quantidade);
122	  END IF;
123	
124	  RETURN NEW;
125	END;
126	$function$;
